      var on = encyTab === tb.id;
      var hid = "ency:tab:" + tb.id;
      addHit(hid, tx, tabY, tabW, tabH);
      markBox(hid, tx, tabY, tabW, tabH);
      box(ctx, tx, tabY, tabW, tabH, on ? "#2a2050" : "#1a1430", on ? C.gold : C.cream);
